function SIMULATES(Q, P):
    provP <- { concl(p) : p in proofs(P) }
    provQ <- { concl(q) : q in proofs(Q) }   # as a hash set
    for f in provP:
        if f not in provQ:
            return false
    return true

function SIM_EQUIV(P, Q):
    return SIMULATES(P, Q) and SIMULATES(Q, P)

