function JOIN_PROV(P, Q):
    return PROV(P) UNION PROV(Q)

function MEET_PROV_WITH_SIZE(P, Q):
    result <- empty map
    for f in PROV(P) INTERSECT PROV(Q):
        sP <- min size of a P-proof of f
        sQ <- min size of a Q-proof of f
        result[f] <- sP + sQ        # meet sizes add
    return result

