function COMBINE_PBOUNDS(witnesses):   # list of (c_i, k_i)
    c <- 0
    k <- 0
    for (c_i, k_i) in witnesses:
        c <- c + c_i
        k <- max(k, k_i)
    return (c, k)

function IS_PBOUNDED(system, cx, c, k):
    for f in PROV(system):
        if min_proof_size(system, f) > c * (cx(f) + 1) ** k:
            return false
    return true
